control-3.solution:
fn years_to_double(start: u32, rate_percent: u32) -> u32 {
    let mut balance = start;
    let mut years = 0;
    loop {
        if balance >= start * 2 {
            break years;
        }
        balance += balance * rate_percent / 100;
        years += 1;
    }
}

