fn check_password(p: &str) -> String {
    let lower = p.to_lowercase();
    let mut has_digit = false;
    for c in p.chars() {
        if c >= '0' && c <= '9' {
            has_digit = true;
        }
    }
    if p.chars().count() < 8 {
        "too short".to_string()
    } else if lower == "password" || lower == "qwertyuiop" {
        "too common".to_string()
    } else if !has_digit {
        "needs a digit".to_string()
    } else {
        "ok".to_string()
    }
}

