fn main() {
    let mut best_name = String::new();
    let mut best_score = i64::MIN;
    // read every line, split it into name and score, and keep the best
    for line in io::stdin().lines() {
        let line = line.expect("failed to read a line");
        let mut parts = Vec::new();
        for part in line.split_whitespace() {
            parts.push(part);
        }
        let score: i64 = parts[1].parse().expect("not a score");
        if score > best_score {
            best_score = score;
            best_name = parts[0].to_string();
        }
    }
    println!("best: {best_name} with {best_score}");
}

