use std::io;

fn main() {
    let secret = 7;
    let mut guesses = 0;
    let mut won = false;
    for line in io::stdin().lines() {
        let line = line.expect("failed to read a line");
        let text = line.trim();
        let guess: i32 = match text.parse() {
            Ok(n) => n,
            Err(_) => {
                println!("not a number: {text}");
                continue;
            }
        };
        guesses += 1;
        if guess < secret {
            println!("too low");
        } else if guess > secret {
            println!("too high");
        } else {
            println!("correct! guesses: {guesses}");
            won = true;
            break;
        }
    }
    if !won {
        println!("out of guesses");
    }
}

