use std::io::Read;

// Split "name score" into the name and the score.
fn parse_line(line: &str) -> (&str, u32) {
    let bytes = line.as_bytes();
    for i in 0..bytes.len() {
        if bytes[i] == b' ' {
            let score: u32 = line[i + 1..].trim().parse().expect("bad score");
            return (&line[..i], score);
        }
    }
    (line, 0)
}

fn main() {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).expect("could not read input");
    // Loop over input.lines(), keep the top player and the total, then print them.
    let mut top_name = "";
    let mut top_score = 0;
    let mut total = 0;
    for line in input.lines() {
        let (name, score) = parse_line(line);
        total += score;
        if score > top_score {
            top_name = name;
            top_score = score;
        }
    }
    println!("top: {} ({})", top_name, top_score);
    println!("total: {}", total);
}

