struct Item {
    name: String,
    price_cents: u32,
    quantity: u32,
}

fn main() {
    let mut items: Vec<Item> = Vec::new();
    for line in std::io::stdin().lines() {
        let line = line.expect("could not read input");
        // The words of the line: parts[0] is the name, parts[1] the price, parts[2] the quantity.
        let parts: Vec<&str> = line.split_whitespace().collect();
        items.push(Item {
            name: parts[0].to_string(),
            price_cents: parts[1].parse().expect("price should be a number"),
            quantity: parts[2].parse().expect("quantity should be a number"),
        });
    }
    let mut total = 0;
    for item in &items {
        let value = item.price_cents * item.quantity;
        println!("{}: {}", item.name, value);
        total += value;
    }
    println!("total: {}", total);
}

