struct Account {
    balance_cents: u64,
    transactions: u32,
}

impl Account {
    fn deposit(&mut self, amount: u64) {
        self.balance_cents += amount;
        self.transactions += 1;
    }

    fn withdraw(&mut self, amount: u64) -> bool {
        if amount > self.balance_cents {
            return false;
        }
        self.balance_cents -= amount;
        self.transactions += 1;
        true
    }

    fn transfer(&mut self, to: &mut Account, amount: u64) -> bool {
        if !self.withdraw(amount) {
            return false;
        }
        to.deposit(amount);
        true
    }
}

