struct Thermostat {
    current: i32,
    target: i32,
}

impl Thermostat {
    fn set_target(&mut self, target: i32) {
        self.target = if target < 10 {
            10
        } else if target > 30 {
            30
        } else {
            target
        };
    }

    fn tick(&mut self) {
        if self.current < self.target {
            self.current += 1;
        } else if self.current > self.target {
            self.current -= 1;
        }
    }

    fn is_stable(&self) -> bool {
        self.current == self.target
    }
}

methods-2.harness:
fn at(current: i32) -> Thermostat {
    Thermostat { current, target: current }
}

#[test]
fn sets_a_normal_target() {
    let mut t = at(18);
    t.set_target(22);
    assert_eq!(t.target, 22, "target after set_target(22)");
}

