fn clamps_low_and_high_targets() {
    let mut t = at(18);
    t.set_target(-5);
    assert_eq!(t.target, 10, "target after set_target(-5)");
    t.set_target(99);
    assert_eq!(t.target, 30, "target after set_target(99)");
}

#[test]
fn ticks_up_one_degree() {
    let mut t = at(18);
    t.set_target(20);
    t.tick();
    assert_eq!(t.current, 19, "current after one tick from 18 toward 20");
}

#[test]
fn ticks_down_one_degree() {
    let mut t = at(25);
    t.set_target(20);
    t.tick();
    assert_eq!(t.current, 24, "current after one tick from 25 toward 20");
}

#[test]
fn becomes_stable_and_stays_there() {
    let mut t = at(18);
    t.set_target(20);
    assert_eq!(t.is_stable(), false, "is_stable at 18 with target 20");
    t.tick();
    t.tick();
    t.tick();
    assert_eq!((t.current, t.is_stable()), (20, true), "(current, is_stable) after three ticks from 18 toward 20");
}

