struct Cart {
    prices: Vec<u32>,
    max_items: usize,
}

impl Cart {
    fn new(max_items: usize) -> Self {
        Self { prices: Vec::new(), max_items }
    }

    fn count(&self) -> usize {
        self.prices.len()
    }

    fn total(&self) -> u32 {
        let mut sum = 0;
        for price in &self.prices {
            sum += price;
        }
        sum
    }
}

impl Cart {
    fn add(&mut self, price_cents: u32) -> bool {
        if self.prices.len() >= self.max_items {
            return false;
        }
        self.prices.push(price_cents);
        true
    }
}

