struct Stats {
    count: i32,
    total: i32,
    highest: i32,
}

impl Stats {
    fn new() -> Self {
        Self { count: 0, total: 0, highest: i32::MIN }
    }

    fn record(&mut self, value: i32) -> &mut Self {
        self.count += 1;
        self.total += value;
        if value > self.highest {
            self.highest = value;
        }
        self
    }

    fn average(&self) -> i32 {
        if self.count == 0 {
            return 0;
        }
        self.total / self.count
    }
}

