struct Garage {
    capacity: u32,
    parked: u32,
}

// impl Garage here
impl Garage {
    fn new(capacity: u32) -> Self {
        Self { capacity, parked: 0 }
    }

    fn enter(&mut self) -> bool {
        if self.parked >= self.capacity {
            return false;
        }
        self.parked += 1;
        true
    }

    fn leave(&mut self) -> bool {
        if self.parked == 0 {
            return false;
        }
        self.parked -= 1;
        true
    }

    fn status(&self) -> String {
        format!("{}/{}", self.parked, self.capacity)
    }
}

fn main() {
    let mut first = String::new();
    std::io::stdin().read_line(&mut first).expect("could not read input");
    let capacity: u32 = first.trim().parse().expect("capacity should be a number");
    let mut garage = Garage::new(capacity);
    for line in std::io::stdin().lines() {
        let line = line.expect("could not read input");
        let command = line.trim();
        // TODO: handle "enter", "leave" and "status"
        if command == "enter" {
            if garage.enter() {
                println!("car in ({})", garage.status());
            } else {
                println!("full");
            }
        } else if command == "leave" {
            if garage.leave() {
                println!("car out ({})", garage.status());
            } else {
                println!("empty");
            }
        } else if command == "status" {
            println!("{} parked", garage.status());
        }
    }
}

