// Define Task and TodoList, with an impl block for TodoList.
struct Task {
    text: String,
    done: bool,
}

struct TodoList {
    tasks: Vec<Task>,
}

impl TodoList {
    fn new() -> Self {
        Self { tasks: Vec::new() }
    }

    fn add(&mut self, text: &str) -> usize {
        self.tasks.push(Task { text: text.to_string(), done: false });
        self.tasks.len()
    }

    fn complete(&mut self, number: usize) -> bool {
        if number == 0 || number > self.tasks.len() {
            return false;
        }
        self.tasks[number - 1].done = true;
        true
    }

    fn print(&self) {
        if self.tasks.is_empty() {
            println!("nothing to do");
        }
        for i in 0..self.tasks.len() {
            let task = &self.tasks[i];
            let mark = if task.done { "x" } else { " " };
            println!("{}. [{}] {}", i + 1, mark, task.text);
        }
    }
}

fn main() {
    let mut todo = TodoList::new();
    for line in std::io::stdin().lines() {
        let line = line.expect("could not read input");
        let parts: Vec<&str> = line.split_whitespace().collect();
        // TODO: handle "add", "done" and "list"
        if parts[0] == "add" {
            let number = todo.add(&line[4..]);
            println!("added #{}", number);
        } else if parts[0] == "done" {
            let number: usize = parts[1].parse().expect("task number should be a number");
            if todo.complete(number) {
                println!("completed #{}", number);
            } else {
                println!("no task {}", number);
            }
        } else if parts[0] == "list" {
            todo.print();
        }
    }
}

