enum Vend {
    Idle,
    HasCoin,
    Dispensing,
}

fn on_event(state: Vend, event: &str) -> Vend {
    match state {
        Vend::Idle => {
            if event == "coin" { Vend::HasCoin } else { Vend::Idle }
        }
        Vend::HasCoin => match event {
            "push" => Vend::Dispensing,
            "refund" => Vend::Idle,
            _ => Vend::HasCoin,
        },
        Vend::Dispensing => {
            if event == "done" { Vend::Idle } else { Vend::Dispensing }
        }
    }
}

