enum Transaction {
    Deposit(u64),
    Withdraw(u64),
    Transfer { amount: u64, to: String },
    Balance,
}

fn parse_amount(word: Option<&str>) -> Option<u64> {
    let Some(word) = word else {
        return None;
    };
    let Ok(amount) = word.parse::<u64>() else {
        return None;
    };
    Some(amount)
}

fn parse_transaction(line: &str) -> Option<Transaction> {
    let mut words = line.split_whitespace();
    let Some(name) = words.next() else {
        return None;
    };
    let transaction = match name {
        "deposit" => {
            let Some(amount) = parse_amount(words.next()) else {
                return None;
            };
            Transaction::Deposit(amount)
        }
        "withdraw" => {
            let Some(amount) = parse_amount(words.next()) else {
                return None;
            };
            Transaction::Withdraw(amount)
        }
        "transfer" => {
            let Some(amount) = parse_amount(words.next()) else {
                return None;
            };
            let Some(to) = words.next() else {
                return None;
            };
            Transaction::Transfer { amount, to: to.to_string() }
        }
        "balance" => Transaction::Balance,
        _ => return None,
    };
    if words.next().is_some() {
        return None;
    }
    Some(transaction)
}

