use std::io;

fn main() {
    let mut line = String::new();
    io::stdin().read_line(&mut line).expect("could not read input");
    let text = line.trim_end().to_lowercase();

    // count each kind of character with a match on c
    let mut vowels = 0;
    let mut consonants = 0;
    let mut digits = 0;
    let mut spaces = 0;
    let mut other = 0;
    for c in text.chars() {
        match c {
            'a' | 'e' | 'i' | 'o' | 'u' => vowels += 1,
            'a'..='z' => consonants += 1,
            '0'..='9' => digits += 1,
            ' ' => spaces += 1,
            _ => other += 1,
        }
    }
    println!("vowels: {vowels}");
    println!("consonants: {consonants}");
    println!("digits: {digits}");
    println!("spaces: {spaces}");
    println!("other: {other}");
}

