use std::io::{self, BufRead};

fn main() {
    let mut balance: u32 = 0;
    for line in io::stdin().lock().lines() {
        let line = line.expect("could not read a line");
        let words: Vec<&str> = line.split_whitespace().collect();
        // match words.as_slice() { ... }
        match words.as_slice() {
            ["deposit", amount] => match amount.parse::<u32>() {
                Ok(n) => {
                    balance += n;
                    println!("balance: {balance}");
                }
                Err(_) => println!("unknown command"),
            },
            ["withdraw", amount] => match amount.parse::<u32>() {
                Ok(n) if n > balance => println!("insufficient funds"),
                Ok(n) => {
                    balance -= n;
                    println!("balance: {balance}");
                }
                Err(_) => println!("unknown command"),
            },
            ["balance"] => println!("balance: {balance}"),
            _ => println!("unknown command"),
        }
    }
}

fn pair_sums(values: &[i32]) -> Vec<i32> {
    let mut sums = Vec::new();
    let mut rest = values;
    while let [a, b, tail @ ..] = rest {
        sums.push(a + b);
        rest = tail;
    }
    if let [last] = rest {
        sums.push(*last);
    }
    sums
}

