    price_cents: u32,
}

fn most_valuable(items: &[Product]) -> Option<String> {
    let [first, rest @ ..] = items else {
        return None;
    };
    let mut best = first;
    for p in rest {
        if p.qty * p.price_cents > best.qty * best.price_cents {
            best = p;
        }
    }
    Some(best.name.clone())
}

