use std::collections::HashMap;

fn sell(stock: &mut HashMap<String, u32>, item: &str, qty: u32) -> bool {
    let Some(have) = stock.get_mut(item) else {
        return false;
    };
    if *have < qty {
        return false;
    }
    *have -= qty;
    if *have == 0 {
        stock.remove(item);
    }
    true
}

