use std::collections::HashSet;
use std::io;

fn main() {
    let mut moves = String::new();
    io::stdin().read_line(&mut moves).expect("could not read moves");
    let mut pos = (0, 0);
    let mut visited: HashSet<(i32, i32)> = HashSet::new();
    visited.insert(pos);
    let mut revisits = 0;
    for c in moves.chars() {
        match c {
            'U' => pos.1 += 1,
            'D' => pos.1 -= 1,
            'L' => pos.0 -= 1,
            'R' => pos.0 += 1,
            _ => continue,
        }
        if !visited.insert(pos) {
            revisits += 1;
        }
    }
    println!("visited {} cells", visited.len());
    println!("revisited {revisits} times");
}

