fn is_palindrome(s: &str) -> bool {
    let mut letters: Vec<char> = Vec::new();
    for c in s.to_lowercase().chars() {
        if c.is_alphanumeric() {
            letters.push(c);
        }
    }
    let n = letters.len();
    for i in 0..n / 2 {
        if letters[i] != letters[n - 1 - i] {
            return false;
        }
    }
    true
}

