        let Ok(score) = score.trim().parse::<u32>() else {
            skipped += 1;
            continue;
        };
        if count == 0 || score > best_score {
            best_name = name.trim();
            best_score = score;
        }
        count += 1;
        total += score;
    }
    println!("students: {count}");
    println!("average: {:.1}", total as f64 / count as f64);
    println!("best: {best_name} ({best_score})");
    println!("skipped: {skipped}");
}

