impl fmt::Display for Grid {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut out = String::new();
        for (i, row) in self.rows.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            for n in row {
                out.push_str(&format!("{:>4}", n));
            }
        }
        write!(f, "{out}")
    }
}

