// Write the BookingError enum here.
#[derive(Debug, PartialEq)]
enum BookingError {
    ZeroTickets,
    OverLimit { requested: u32, limit: u32 },
    SoldOut { available: u32 },
}

fn book(available: u32, requested: u32) -> Result<u32, BookingError> {
    if requested == 0 {
        return Err(BookingError::ZeroTickets);
    }
    if requested > 6 {
        return Err(BookingError::OverLimit { requested, limit: 6 });
    }
    if requested > available {
        return Err(BookingError::SoldOut { available });
    }
    Ok(available - requested)
}

