use std::fmt;

#[derive(Debug, PartialEq)]
enum GradeError {
    Negative(i32),
    AboveMax(i32),
}

impl fmt::Display for GradeError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            GradeError::Negative(s) => write!(f, "score cannot be negative: {s}"),
            GradeError::AboveMax(s) => write!(f, "score {s} is above the maximum of 100"),
        }
    }
}

fn letter_grade(score: i32) -> Result<char, GradeError> {
    if score < 0 {
        return Err(GradeError::Negative(score));
    }
    if score > 100 {
        return Err(GradeError::AboveMax(score));
    }
    let grade = match score {
        90.. => 'A',
        80.. => 'B',
        70.. => 'C',
        60.. => 'D',
        _ => 'F',
    };
    Ok(grade)
}

