use std::num::ParseIntError;

// PortError, Port, and impl Port { parse, number }
#[derive(Debug, PartialEq)]
enum PortError {
    NotANumber(ParseIntError),
    Zero,
    Reserved(u16),
}

struct Port(u16);

impl Port {
    fn parse(text: &str) -> Result<Port, PortError> {
        let n: u16 = text.trim().parse().map_err(PortError::NotANumber)?;
        if n == 0 {
            return Err(PortError::Zero);
        }
        if n < 1024 {
            return Err(PortError::Reserved(n));
        }
        Ok(Port(n))
    }

    fn number(&self) -> u16 {
        self.0
    }
}

