fn smallest<T: PartialOrd + Copy>(items: &[T]) -> Option<T> {
    if items.is_empty() {
        return None;
    }
    let mut best = items[0];
    for &item in items {
        if item < best {
            best = item;
        }
    }
    Some(best)
}

