use std::fmt::Display;

fn join_all<T: Display>(items: &[T], separator: &str) -> String {
    let mut out = String::new();
    let mut first = true;
    for item in items {
        if !first {
            out.push_str(separator);
        }
        out.push_str(&item.to_string());
        first = false;
    }
    out
}

