struct Shelf<T> {
    items: Vec<T>,
    capacity: usize,
}

impl<T> Shelf<T> {
    fn new(capacity: usize) -> Self {
        Shelf { items: Vec::new(), capacity }
    }

    fn len(&self) -> usize {
        self.items.len()
    }

    fn add(&mut self, item: T) -> Result<(), T> {
        if self.items.len() >= self.capacity {
            return Err(item);
        }
        self.items.push(item);
        Ok(())
    }
}

impl Shelf<f64> {
    fn total(&self) -> f64 {
        let mut sum = 0.0;
        for price in &self.items {
            sum += price;
        }
        sum
    }
}

