trait Summary {
    fn summarize(&self) -> String;
}

struct Post {
    user: String,
    text: String,
}

impl Summary for Post {
    fn summarize(&self) -> String {
        format!("@{}: {}", self.user, self.text)
    }
}

fn digest<T: Summary>(items: &[T]) -> String {
    let mut out = String::new();
    let mut n = 0;
    for item in items {
        n += 1;
        if n > 1 {
            out.push('\n');
        }
        out.push_str(&format!("{}. {}", n, item.summarize()));
    }
    out
}

