impl fmt::Display for RaceTime {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let h = self.seconds / 3600;
        let m = self.seconds % 3600 / 60;
        let s = self.seconds % 60;
        if h > 0 {
            write!(f, "{}:{:02}:{:02}", h, m, s)
        } else {
            write!(f, "{}:{:02}", m, s)
        }
    }
