use std::fmt::Display;

fn count_matches<T>(items: &[T], target: &T) -> String
where
    T: Display + PartialEq,
{
    let mut count = 0;
    for item in items {
        if item == target {
            count += 1;
        }
    }
    format!("{count} x {target}")
}

