use std::io::BufRead;
use std::str::FromStr;

#[derive(Debug)]
enum Side {
    Left,
    Right,
}

#[derive(Debug)]
enum Command {
    Forward(u32),
    Turn(Side),
    Stop,
}

impl FromStr for Command {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let unknown = || format!("unknown command: {s}");
        let words: Vec<&str> = s.split_whitespace().collect();
        match words.as_slice() {
            ["forward", n] => n.parse::<u32>().map(Command::Forward).map_err(|_| unknown()),
            ["turn", "left"] => Ok(Command::Turn(Side::Left)),
            ["turn", "right"] => Ok(Command::Turn(Side::Right)),
            ["stop"] => Ok(Command::Stop),
            _ => Err(unknown()),
        }
    }
}

fn main() {
    let stdin = std::io::stdin();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        match line.trim().parse::<Command>() {
            Ok(Command::Forward(n)) => println!("forward {n} steps"),
            Ok(Command::Turn(side)) => println!("turn {:?}", side),
            Ok(Command::Stop) => println!("stop"),
            Err(e) => println!("error: {e}"),
        }
    }
}

