impl<'a> KeyValues<'a> {
    fn get(&self, key: &str) -> Option<&'a str> {
        for pair in self.input.split(';') {
            if let Some((k, v)) = pair.split_once('=') {
                if k.trim() == key {
                    return Some(v.trim());
                }
            }
        }
        None
    }
}

