struct Person<'a> {
    name: &'a str,
    city: &'a str,
}

fn parse_people(text: &str) -> Vec<Person<'_>> {
    let mut people = Vec::new();
    for line in text.lines() {
        if let Some((name, city)) = line.split_once(',') {
            people.push(Person { name: name.trim(), city: city.trim() });
        }
    }
    people
}

fn main() {
    let mut input = String::new();
    std::io::stdin().read_to_string(&mut input).unwrap();
    let (wanted, rest) = input.split_once('\n').unwrap_or((input.as_str(), ""));
    let people = parse_people(rest);
    let mut found = 0;
    for p in &people {
        if p.city == wanted.trim() {
            println!("{}", p.name);
            found += 1;
        }
    }
    println!("{found} found");
}

