struct Sentences<'a> {
    rest: &'a str,
}

impl<'a> Sentences<'a> {
    fn new(text: &'a str) -> Self {
        Sentences { rest: text }
    }

    fn next_sentence(&mut self) -> Option<&'a str> {
        while !self.rest.is_empty() {
            let (piece, rest) = match self.rest.find('.') {
                Some(i) => (&self.rest[..i], &self.rest[i + 1..]),
                None => (self.rest, ""),
            };
            self.rest = rest;
            let piece = piece.trim();
            if !piece.is_empty() {
                return Some(piece);
            }
        }
        None
    }
}

