    fn run(&mut self, events: &[&str]) {
        for event in events {
            for p in &mut self.plugins {
                p.handle(event);
            }
        }
    }

    fn summaries(&self) -> Vec<String> {
        let mut out = Vec::new();
        for p in &self.plugins {
            out.push(p.summary());
        }
        out
    }
}

