use std::collections::HashMap;
use std::io::BufRead;

trait Command {
    fn run(&self, args: &[i64]) -> Result<i64, String>;
}

struct Add;
struct Mul;
struct Div;

impl Command for Add {
    fn run(&self, args: &[i64]) -> Result<i64, String> {
        let mut sum = 0;
        for a in args {
            sum += a;
        }
        Ok(sum)
    }
}

impl Command for Mul {
    fn run(&self, args: &[i64]) -> Result<i64, String> {
        let mut product = 1;
        for a in args {
            product *= a;
        }
        Ok(product)
    }
}

impl Command for Div {
    fn run(&self, args: &[i64]) -> Result<i64, String> {
        match args {
            [_, 0] => Err(String::from("division by zero")),
            [a, b] => Ok(a / b),
            _ => Err(String::from("div needs 2 numbers")),
        }
    }
}

fn execute(commands: &HashMap<String, Box<dyn Command>>, line: &str) -> Result<i64, String> {
    let mut words = line.split_whitespace();
    let name = words.next().unwrap_or("");
    let command = commands.get(name).ok_or(format!("unknown command {name}"))?;
    let mut args = Vec::new();
    for w in words {
        args.push(w.parse::<i64>().map_err(|_| format!("bad number {w}"))?);
    }
    command.run(&args)
}

fn main() {
    let mut commands: HashMap<String, Box<dyn Command>> = HashMap::new();
    commands.insert(String::from("add"), Box::new(Add));
    commands.insert(String::from("mul"), Box::new(Mul));
    commands.insert(String::from("div"), Box::new(Div));

    let stdin = std::io::stdin();
    for line in stdin.lock().lines() {
        let line = line.unwrap();
        match execute(&commands, &line) {
            Ok(n) => println!("{n}"),
            Err(e) => println!("error: {e}"),
        }
    }
}

