trait-objects-7.solution:
use std::any::Any;

trait Event: Any {
    fn name(&self) -> String;
}

struct Login {
    user: String,
}

struct Purchase {
    amount_cents: u32,
}

impl Event for Login {
    fn name(&self) -> String {
        String::from("login")
    }
}

impl Event for Purchase {
    fn name(&self) -> String {
        String::from("purchase")
    }
}

fn logins(events: &[Box<dyn Event>]) -> Vec<String> {
    let mut users = Vec::new();
    for e in events {
        let any: &dyn Any = e.as_ref();
        if let Some(login) = any.downcast_ref::<Login>() {
            users.push(login.user.clone());
        }
    }
    users
}

