closures-4.solution:
fn retry<F: FnMut() -> Result<u32, String>>(attempts: u32, mut op: F) -> Result<u32, String> {
    let mut last = Err(String::from("no attempts"));
    for _ in 0..attempts {
        last = op();
        if last.is_ok() {
            return last;
        }
    }
    last
}

