iterators-7.solution:
struct Collatz {
    current: u64,
    done: bool,
}

impl Collatz {
    fn new(start: u64) -> Self {
        Collatz { current: start, done: false }
    }
}

impl Iterator for Collatz {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        if self.done {
            return None;
        }
        let value = self.current;
        if value == 1 {
            self.done = true;
        } else if value % 2 == 0 {
            self.current = value / 2;
        } else {
            self.current = 3 * value + 1;
        }
        Some(value)
    }
}

