iterators-7.solution:
struct Pages<'a> {
    items: &'a [i32],
    size: usize,
}

impl<'a> Iterator for Pages<'a> {
    type Item = &'a [i32];

    fn next(&mut self) -> Option<Self::Item> {
        if self.items.is_empty() {
            return None;
        }
        let n = self.size.min(self.items.len());
        let (page, rest) = self.items.split_at(n);
        self.items = rest;
        Some(page)
    }
}

