mod semver {
    fn parse(v: &str) -> (u64, u64, u64) {
        let parts: Vec<u64> = v.split('.').map(|p| p.parse().unwrap()).collect();
        (parts[0], parts[1], parts[2])
    }

    pub fn tilde_matches(req: &str, version: &str) -> bool {
        let r = parse(req);
        let v = parse(version);
        v >= r && v.0 == r.0 && v.1 == r.1
    }
}

