use itertools::Itertools;

fn leaderboard_line(scores: &[(&str, u32)]) -> String {
    scores
        .iter()
        .sorted_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(b.0)))
        .map(|(name, score)| format!("{name}:{score}"))
        .join(", ")
}

