#[derive(Debug)]
enum List {
    Cons(i32, Box<List>),
    Nil,
}

use List::{Cons, Nil};

fn from_slice(values: &[i32]) -> List {
    match values {
        [] => Nil,
        [first, rest @ ..] => Cons(*first, Box::new(from_slice(rest))),
    }
}

fn len(list: &List) -> usize {
    match list {
        Cons(_, rest) => 1 + len(rest),
        Nil => 0,
    }
}

fn largest(list: &List) -> Option<i32> {
    match list {
        Nil => None,
        Cons(value, rest) => match largest(rest) {
            Some(best) if best > *value => Some(best),
            _ => Some(*value),
        },
    }
}

