struct Node {
    key: u32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

fn insert(tree: &mut Option<Box<Node>>, key: u32) {
    match tree {
        None => *tree = Some(Box::new(Node { key, left: None, right: None })),
        Some(node) => {
            if key < node.key {
                insert(&mut node.left, key);
            } else {
                insert(&mut node.right, key);
            }
        }
    }
}

fn contains(tree: &Option<Box<Node>>, key: u32) -> bool {
    match tree {
        None => false,
        Some(node) if key == node.key => true,
        Some(node) if key < node.key => contains(&node.left, key),
        Some(node) => contains(&node.right, key),
    }
}

fn height(tree: &Option<Box<Node>>) -> usize {
    match tree {
        None => 0,
        Some(node) => 1 + height(&node.left).max(height(&node.right)),
    }
}

