use std::rc::Rc;

#[derive(Debug)]
struct Player {
    name: String,
}

struct Team {
    members: Vec<Rc<Player>>,
}

fn share(player: Player, teams: &mut [Team]) -> Rc<Player> {
    let shared = Rc::new(player);
    for team in teams.iter_mut() {
        team.members.push(Rc::clone(&shared));
    }
    shared
}

fn on_both(player: &Rc<Player>, a: &Team, b: &Team) -> bool {
    let in_team = |t: &Team| t.members.iter().any(|m| Rc::ptr_eq(m, player));
    in_team(a) && in_team(b)
}

