use std::cell::Cell;

struct Report {
    data: Vec<u32>,
    cached_total: Cell<Option<u32>>,
    computations: Cell<u32>,
}

impl Report {
    fn new(data: Vec<u32>) -> Report {
        Report { data, cached_total: Cell::new(None), computations: Cell::new(0) }
    }

    fn total(&self) -> u32 {
        if let Some(t) = self.cached_total.get() {
            return t;
        }
        let t = self.data.iter().sum();
        self.computations.set(self.computations.get() + 1);
        self.cached_total.set(Some(t));
        t
    }
}

