use std::cell::RefCell;
use std::rc::Rc;

#[derive(Debug)]
struct Account {
    balance: u64,
}

type AccountRef = Rc<RefCell<Account>>;

fn transfer(from: &AccountRef, to: &AccountRef, amount: u64) -> Result<(), String> {
    if Rc::ptr_eq(from, to) {
        return Err("same account".to_string());
    }
    let mut source = from.borrow_mut();
    if source.balance < amount {
        return Err("insufficient funds".to_string());
    }
    source.balance -= amount;
    to.borrow_mut().balance += amount;
    Ok(())
}

