use std::cell::RefCell;
use std::rc::Rc;

struct User {
    name: String,
    following: Vec<UserRef>,
    followers: u32,
}

type UserRef = Rc<RefCell<User>>;

fn user(name: &str) -> UserRef {
    Rc::new(RefCell::new(User { name: name.to_string(), following: Vec::new(), followers: 0 }))
}

fn follow(who: &UserRef, target: &UserRef) {
    if Rc::ptr_eq(who, target) {
        return;
    }
    if who.borrow().following.iter().any(|u| Rc::ptr_eq(u, target)) {
        return;
    }
    who.borrow_mut().following.push(Rc::clone(target));
    target.borrow_mut().followers += 1;
}

fn most_followed(users: &[UserRef]) -> Option<String> {
    let mut best: Option<&UserRef> = None;
    for u in users {
        match best {
            Some(b) if b.borrow().followers >= u.borrow().followers => {}
            _ => best = Some(u),
        }
    }
    best.map(|u| u.borrow().name.clone())
}

