use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Playlist {
    name: String,
    tracks: RefCell<Vec<Rc<Track>>>,
}

struct Track {
    title: String,
    playlist: RefCell<Weak<Playlist>>,
}

impl Drop for Playlist {
    fn drop(&mut self) {
        println!("dropping playlist {}", self.name);
    }
}

impl Drop for Track {
    fn drop(&mut self) {
        println!("dropping track {}", self.title);
    }
}

fn add(list: &Rc<Playlist>, title: &str) {
    let track = Rc::new(Track { title: title.to_string(), playlist: RefCell::new(Weak::new()) });
    *track.playlist.borrow_mut() = Rc::downgrade(list);
    list.tracks.borrow_mut().push(track);
}

fn main() {
    let list = Rc::new(Playlist { name: String::from("Night Drive"), tracks: RefCell::new(Vec::new()) });
    add(&list, "Neon");
    add(&list, "Rain");
    println!("{} has {} tracks", list.name, list.tracks.borrow().len());
    let first = Rc::clone(&list.tracks.borrow()[0]);
    if let Some(p) = first.playlist.borrow().upgrade() {
        println!("{} is on {}", first.title, p.name);
    }
    drop(first);
    println!("end of main");
}

