        if self.items.len() == self.capacity {
            self.items.remove(0);
        }
        self.items.push(value);
    }

    fn latest(&self) -> Option<i32> {
        self.items.last().copied()
    }

    fn oldest(&self) -> Option<i32> {
        self.items.first().copied()
    }

    fn len(&self) -> usize {
        self.items.len()
    }
}

