use std::thread;

fn apply_discount(prices: &mut [u32], percent: u32, workers: usize) {
    let size = prices.len().div_ceil(workers).max(1);
    thread::scope(|s| {
        for chunk in prices.chunks_mut(size) {
            s.spawn(move || {
                for p in chunk {
                    *p = *p * (100 - percent) / 100;
                }
            });
        }
    });
}

