use std::sync::mpsc;
use std::thread;

fn search_parallel(docs: Vec<String>, needle: &str) -> Vec<usize> {
    let (tx, rx) = mpsc::channel();
    for (i, doc) in docs.into_iter().enumerate() {
        let tx = tx.clone();
        let needle = needle.to_string();
        thread::spawn(move || {
            if doc.contains(&needle) {
                tx.send(i).unwrap();
            }
        });
    }
    drop(tx);
    let mut found: Vec<usize> = rx.iter().collect();
    found.sort();
    found
}

