use std::collections::BTreeMap;
use std::sync::Mutex;
use std::thread;

fn tally_votes(stations: &[Vec<&str>]) -> BTreeMap<String, u32> {
    let totals = Mutex::new(BTreeMap::new());
    thread::scope(|s| {
        for ballots in stations {
            s.spawn(|| {
                for name in ballots.iter() {
                    let mut map = totals.lock().unwrap();
                    *map.entry(name.to_string()).or_insert(0) += 1;
                }
            });
        }
    });
    totals.into_inner().unwrap()
}

