use std::sync::Mutex;

#[derive(Debug)]
struct Account {
    id: u32,
    balance: Mutex<i64>,
}

fn transfer(from: &Account, to: &Account, amount: i64) {
    if from.id == to.id {
        return;
    }
    let (mut from_balance, mut to_balance) = if from.id < to.id {
        let f = from.balance.lock().unwrap();
        let t = to.balance.lock().unwrap();
        (f, t)
    } else {
        let t = to.balance.lock().unwrap();
        let f = from.balance.lock().unwrap();
        (f, t)
    };
    *from_balance -= amount;
    *to_balance += amount;
}

