use std::collections::BTreeSet;
use tokio::sync::{mpsc, oneshot};

enum Cmd {
    Visit(String),
    Count(oneshot::Sender<usize>),
}

async fn visitor_log(mut rx: mpsc::Receiver<Cmd>) {
    let mut visitors = BTreeSet::new();
    while let Some(cmd) = rx.recv().await {
        match cmd {
            Cmd::Visit(name) => {
                visitors.insert(name);
            }
            Cmd::Count(reply) => {
                let _ = reply.send(visitors.len());
            }
        }
    }
}

async-5.harness:
async fn count(tx: &mpsc::Sender<Cmd>) -> usize {
    let (reply, answer) = oneshot::channel();
    tx.send(Cmd::Count(reply)).await.unwrap();
    answer.await.unwrap()
}

fn run<F: std::future::Future>(future: F) -> F::Output {
    tokio::runtime::Runtime::new().unwrap().block_on(future)
}

#[test]
fn starts_with_no_visitors() {
    let n = run(async {
        let (tx, rx) = mpsc::channel(8);
        tokio::spawn(visitor_log(rx));
        count(&tx).await
    });
    assert_eq!(n, 0, "Count before any visits");
}

#[test]
fn counts_different_visitors_once() {
    let n = run(async {
        let (tx, rx) = mpsc::channel(8);
        tokio::spawn(visitor_log(rx));
        for name in ["ana", "bo", "ana", "cy", "bo"] {
            tx.send(Cmd::Visit(name.to_string())).await.unwrap();
        }
        count(&tx).await
    });
    assert_eq!(n, 3, "visits from ana, bo, ana, cy, bo");
}

#[test]
fn counts_change_over_time() {
    let counts = run(async {
        let (tx, rx) = mpsc::channel(8);
        tokio::spawn(visitor_log(rx));
        tx.send(Cmd::Visit(String::from("ana"))).await.unwrap();
        let first = count(&tx).await;
        tx.send(Cmd::Visit(String::from("dee"))).await.unwrap();
        (first, count(&tx).await)
    });
    assert_eq!(counts, (1, 2), "count after 1 visitor, then after 2");
}

