use std::time::Duration;

async fn save_ticket(number: u32) {
    tokio::time::sleep(Duration::from_millis(u64::from(number % 3))).await;
}

async fn issue_ticket(counter: &tokio::sync::Mutex<u32>) -> u32 {
    let mut count = counter.lock().await;
    *count += 1;
    save_ticket(*count).await;
    *count
}

