use std::fmt;

trait Priced {
    fn price_cents(&self) -> u32;
}

struct Book {
    title: String,
    price_cents: u32,
}

trait Sellable: Priced + fmt::Display {
    fn receipt_line(&self) -> String {
        let cents = self.price_cents();
        format!("{}: ${}.{:02}", self, cents / 100, cents % 100)
    }
}

impl fmt::Display for Book {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "{}", self.title)
    }
}

impl Priced for Book {
    fn price_cents(&self) -> u32 {
        self.price_cents
    }
}

impl Sellable for Book {}

fn total_cents<T: Sellable>(items: &[T]) -> u32 {
    items.iter().map(|item| item.price_cents()).sum()
}

