advanced-traits-5.solution:
type ParseResult<T> = Result<T, String>;

fn parse_port(s: &str) -> ParseResult<u16> {
    let port: u16 = s.parse().map_err(|_| format!("not a number: {s}"))?;
    if port == 0 {
        return Err("port 0 is reserved".to_string());
    }
    Ok(port)
}

fn parse_addr(s: &str) -> ParseResult<(String, u16)> {
    let (host, port) = s.split_once(':').ok_or(format!("missing ':' in {s}"))?;
    Ok((host.to_string(), parse_port(port)?))
}

