use std::marker::PhantomData;

struct Draft;
struct Review;
struct Published;

struct Post<S> {
    text: String,
    _state: PhantomData<S>,
}

impl Post<Draft> {
    fn new() -> Self {
        Post { text: String::new(), _state: PhantomData }
    }

    fn write(&mut self, text: &str) {
        self.text.push_str(text);
    }

    fn submit(self) -> Post<Review> {
        Post { text: self.text, _state: PhantomData }
    }
}

impl Post<Review> {
    fn approve(self) -> Post<Published> {
        Post { text: self.text, _state: PhantomData }
    }

    fn reject(self) -> Post<Draft> {
        Post { text: self.text, _state: PhantomData }
    }
}

impl Post<Published> {
    fn content(&self) -> &str {
        &self.text
    }
}

