use std::marker::PhantomData;

// Write the three state markers, Connection<S> and its impl blocks.
struct Disconnected;
struct Connected;
struct Authenticated;

struct Connection<S> {
    host: String,
    _state: PhantomData<S>,
}

impl<S> Connection<S> {
    fn host(&self) -> &str {
        &self.host
    }
}

impl Connection<Disconnected> {
    fn new(host: &str) -> Self {
        Connection { host: host.to_string(), _state: PhantomData }
    }

    fn connect(self) -> Connection<Connected> {
        Connection { host: self.host, _state: PhantomData }
    }
}

impl Connection<Connected> {
    fn login(self, password: &str) -> Result<Connection<Authenticated>, Connection<Connected>> {
        if password == "hunter2" {
            Ok(Connection { host: self.host, _state: PhantomData })
        } else {
            Err(self)
        }
    }
}

impl Connection<Authenticated> {
    fn query(&self, sql: &str) -> String {
        format!("{} ran: {}", self.host, sql)
    }
}

