fn parse_settings(lines: &[&str]) -> Vec<(String, u32)> {
    let mut out = Vec::new();
    for line in lines {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        let Ok(value) = value.trim().parse::<u32>() else {
            continue;
        };
        out.push((key.trim().to_string(), value));
    }
    out
}

