        name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_'),
        "only letters, digits and _ allowed"
    );
    ensure!(!name.starts_with(|c: char| c.is_ascii_digit()), "must not start with a digit");
    Ok(())
