macro_rules! enum_str {
    ($name:ident { $( $variant:ident ),* $(,)? }) => {
        #[derive(Debug, Clone, Copy, PartialEq)]
        enum $name {
            $( $variant ),*
        }

        impl $name {
            fn as_str(&self) -> &'static str {
                match self {
                    $( $name::$variant => stringify!($variant), )*
                }
            }

            fn all() -> Vec<$name> {
                vec![$( $name::$variant ),*]
            }
        }
    };
}

