macro_rules! state_machine {
    ($($from:ident + $event:ident => $to:ident),* $(,)?) => {
        fn next_state(state: &str, event: &str) -> Option<&'static str> {
            match (state, event) {
                $( (stringify!($from), stringify!($event)) => Some(stringify!($to)), )*
                _ => None,
            }
        }
    };
}

