fn sum_raw(values: &[i32]) -> i32 {
    let p = values.as_ptr();
    let mut total = 0;
    for i in 0..values.len() {
        // SAFETY: i < values.len(), so p.add(i) points to an element of the slice.
        total += unsafe { *p.add(i) };
    }
    total
}

