fn reverse_raw(v: &mut [i32]) {
    let len = v.len();
    if len < 2 {
        return;
    }
    let p = v.as_mut_ptr();
    let mut i = 0;
    let mut j = len - 1;
    while i < j {
        // SAFETY: i < j < len, so both pointers are inside the slice.
        unsafe {
            std::ptr::swap(p.add(i), p.add(j));
        }
        i += 1;
        j -= 1;
    }
}

