unsafe-2.solution:
/// Adds up values[i] for every i in indexes, without bounds checks.
///
/// # Safety
///
/// Every index in `indexes` must be less than `values.len()`.
unsafe fn sum_at_unchecked(values: &[i64], indexes: &[usize]) -> i64 {
    let mut total = 0;
    for &i in indexes {
        // SAFETY: the caller promises every index is in bounds.
        total += unsafe { *values.get_unchecked(i) };
    }
    total
}

/// Safe wrapper: None if any index is out of range.
fn sum_at(values: &[i64], indexes: &[usize]) -> Option<i64> {
    if indexes.iter().any(|&i| i >= values.len()) {
        return None;
    }
    // SAFETY: we just checked that every index is less than values.len().
    Some(unsafe { sum_at_unchecked(values, indexes) })
}

