use std::cmp::Ordering;
use std::ffi::{c_char, c_int, CString};

unsafe extern "C" {
    fn strcmp(a: *const c_char, b: *const c_char) -> c_int;
}

fn c_compare(a: &str, b: &str) -> Option<Ordering> {
    let a = CString::new(a).ok()?;
    let b = CString::new(b).ok()?;
    // SAFETY: both pointers come from live CStrings, so they're valid and NUL-terminated.
    let result = unsafe { strcmp(a.as_ptr(), b.as_ptr()) };
    Some(result.cmp(&0))
}

