use std::collections::HashSet;

fn has_pair_with_sum(values: &[i64], target: i64) -> bool {
    let mut seen = HashSet::with_capacity(values.len());
    for &v in values {
        if seen.contains(&(target - v)) {
            return true;
        }
        seen.insert(v);
    }
    false
}

