use std::borrow::Cow;

fn clamp_negatives(values: &[i32]) -> Cow<'_, [i32]> {
    let mut result = Cow::Borrowed(values);
    for (i, &v) in values.iter().enumerate() {
        if v < 0 {
            result.to_mut()[i] = 0;
        }
    }
    result
}

