/// Runs jobs in order; returns the time at which each one finishes.
fn finish_times(mut jobs: Vec<u32>) -> Vec<u64> {
    let mut clock = 0u64;
    let mut out = Vec::new();
    while !jobs.is_empty() {
        let job = jobs.remove(0);
        clock += job as u64;
        out.push(clock);
    }
    out
}

