/// Runs jobs in order; returns the time at which each one finishes.
fn finish_times(jobs: Vec<u32>) -> Vec<u64> {
    let mut clock = 0u64;
    let mut out = Vec::with_capacity(jobs.len());
    for job in jobs {
        clock += job as u64;
        out.push(clock);
    }
    out
}

