use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(try_from = "String")]
struct Username(String);

impl TryFrom<String> for Username {
    type Error = String;
    fn try_from(s: String) -> Result<Self, Self::Error> {
        let n = s.chars().count();
        if n < 3 {
            return Err(String::from("username too short"));
        }
        if n > 16 {
            return Err(String::from("username too long"));
        }
        if !s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
            return Err(String::from("username has invalid characters"));
        }
        Ok(Username(s))
    }
}

#[derive(Debug, Deserialize)]
struct Account {
    username: Username,
    level: u8,
}

