use anyhow::{anyhow, bail, Result};
use std::io::BufRead;

fn eval(line: &str) -> Result<i64> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    let [a, op, b] = parts[..] else {
        bail!("expected: <a> <op> <b>");
    };
    let a: i64 = a.parse()?;
    let b: i64 = b.parse()?;
    let result = match op {
        "+" => a.checked_add(b),
        "-" => a.checked_sub(b),
        "*" => a.checked_mul(b),
        "/" => {
            if b == 0 {
                bail!("division by zero");
            }
            a.checked_div(b)
        }
        _ => bail!("unknown operator {op:?}"),
    };
    result.ok_or_else(|| anyhow!("overflow"))
}

fn main() {
    for line in std::io::stdin().lock().lines() {
        let line = line.unwrap();
        match eval(&line) {
            Ok(n) => println!("= {n}"),
            Err(e) => println!("error: {e}"),
        }
    }
}

