fn expand(args: &[String]) -> Vec<String> {
    let mut out = Vec::new();
    let mut done = false;
    for arg in args {
        if done {
            out.push(arg.clone());
            continue;
        }
        if arg == "--" {
            done = true;
            out.push(arg.clone());
        } else if let Some(long) = arg.strip_prefix("--") {
            match long.split_once('=') {
                Some((name, value)) => {
                    out.push(format!("--{name}"));
                    out.push(value.to_string());
                }
                None => out.push(arg.clone()),
            }
        } else if arg.len() > 2 && arg.starts_with('-') && arg[1..].chars().all(|c| c.is_ascii_alphabetic()) {
            for c in arg[1..].chars() {
                out.push(format!("-{c}"));
            }
        } else {
            out.push(arg.clone());
        }
    }
    out
}

