use std::process::ExitCode;

enum CliError {
    Usage,
    Invalid(String),
}

fn run(args: &[String]) -> Result<String, CliError> {
    let [input] = args else {
        return Err(CliError::Usage);
    };
    let (value, unit) = if let Some(v) = input.strip_suffix('C') {
        (v, 'C')
    } else if let Some(v) = input.strip_suffix('F') {
        (v, 'F')
    } else {
        return Err(CliError::Invalid(format!("unknown unit in {input:?}")));
    };
    let n: f64 = value.parse().map_err(|_| CliError::Invalid(format!("bad number in {input:?}")))?;
    Ok(match unit {
        'C' => format!("{:.1}F", n * 9.0 / 5.0 + 32.0),
        _ => format!("{:.1}C", (n - 32.0) * 5.0 / 9.0),
    })
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    match run(&args) {
        Ok(out) => {
            println!("{out}");
            ExitCode::SUCCESS
        }
        Err(CliError::Usage) => {
            eprintln!("usage: temp <value><C|F>");
            ExitCode::from(2)
        }
        Err(CliError::Invalid(msg)) => {
            eprintln!("error: {msg}");
            ExitCode::FAILURE
        }
    }
