        ExitCode::from(2)
    };
    let (count, name) = match args.as_slice() {
        [name] => (10, name),
        [flag, n, name] if flag == "-n" => match n.parse::<usize>() {
            Ok(n) => (n, name),
            Err(_) => return usage(),
        },
        _ => return usage(),
    };
    match std::fs::read_to_string(name) {
        Ok(text) => {
            for line in text.lines().take(count) {
                println!("{line}");
            }
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("head: {name}: {e}");
            ExitCode::FAILURE
        }
    }
}

