use std::process::ExitCode;

fn sum_column(text: &str, column: &str) -> Result<f64, String> {
    let mut lines = text.lines();
    let header = lines.next().unwrap_or("");
    let index = header
        .split(',')
        .position(|name| name.trim() == column)
        .ok_or(format!("unknown column {column:?}"))?;
    let mut total = 0.0;
    for (i, line) in lines.enumerate() {
        if line.trim().is_empty() {
            continue;
        }
        let field = line.split(',').nth(index).unwrap_or("").trim();
        let value: f64 = field.parse().map_err(|_| format!("line {}: {field:?} is not a number", i + 2))?;
        total += value;
    }
    Ok(total)
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let [file, column] = args.as_slice() else {
        eprintln!("usage: colsum <file> <column>");
        return ExitCode::from(2);
    };
    let text = match std::fs::read_to_string(file) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("colsum: {file}: {e}");
            return ExitCode::FAILURE;
        }
    };
    match sum_column(&text, column) {
        Ok(total) => {
            println!("sum of {column}: {total:.2}");
            ExitCode::SUCCESS
        }
        Err(msg) => {
            eprintln!("colsum: {msg}");
            ExitCode::FAILURE
        }
    }
}

