#[derive(Debug, PartialEq)]
enum Command {
    Get { key: String },
    Set { key: String, value: String },
    Del { keys: Vec<String> },
    List { limit: Option<usize> },
}

fn parse_command(args: &[String]) -> Result<Command, String> {
    let Some((cmd, rest)) = args.split_first() else {
        return Err(String::from("missing command"));
    };
    match cmd.as_str() {
        "get" => match rest {
            [key] => Ok(Command::Get { key: key.clone() }),
            _ => Err(String::from("usage: get <key>")),
        },
        "set" => match rest {
            [key, value] => Ok(Command::Set { key: key.clone(), value: value.clone() }),
            _ => Err(String::from("usage: set <key> <value>")),
        },
        "del" if !rest.is_empty() => Ok(Command::Del { keys: rest.to_vec() }),
        "del" => Err(String::from("usage: del <key>...")),
        "list" => match rest {
            [] => Ok(Command::List { limit: None }),
            [flag, n] if flag == "--limit" => n
                .parse()
                .map(|n| Command::List { limit: Some(n) })
                .map_err(|_| String::from("usage: list [--limit N]")),
            _ => Err(String::from("usage: list [--limit N]")),
        },
        other => Err(format!("unknown command {other:?}")),
    }
}

