use std::collections::BTreeMap;

fn page_params(query: &BTreeMap<String, String>) -> Result<(usize, usize), String> {
    let page = match query.get("page") {
        Some(p) => p.parse::<usize>().ok().filter(|&n| n >= 1).ok_or(format!("invalid page {p:?}"))?,
        None => 1,
    };
    let per_page = match query.get("per_page") {
        Some(p) => p
            .parse::<usize>()
            .ok()
            .filter(|n| (1..=100).contains(n))
            .ok_or(String::from("per_page must be 1 to 100"))?,
        None => 20,
    };
    Ok(((page - 1) * per_page, per_page))
}

