use serde::{Deserialize, Serialize};
use serde_json::json;

#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    body: String,
}

#[derive(Debug, Serialize)]
struct Task {
    id: u32,
    title: String,
    done: bool,
}

#[derive(Deserialize)]
struct PatchTask {
    title: Option<String>,
    done: Option<bool>,
}

fn patch_task(task: &mut Task, body: &str) -> Response {
    let Ok(patch) = serde_json::from_str::<PatchTask>(body) else {
        return Response { status: 400, body: json!({ "error": "invalid request body" }).to_string() };
    };
    if patch.title.as_deref().is_some_and(|t| t.trim().is_empty()) {
        return Response { status: 422, body: json!({ "error": "title must not be empty" }).to_string() };
    }
    if let Some(title) = patch.title {
        task.title = title.trim().to_string();
    }
    if let Some(done) = patch.done {
        task.done = done;
    }
    Response { status: 200, body: serde_json::to_string(task).expect("tasks always serialize") }
}

