#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    body: String,
}

#[derive(Debug)]
enum ApiError {
    Validation(BTreeMap<String, String>),
}

impl ApiError {
    fn into_response(self) -> Response {
        match self {
            ApiError::Validation(fields) => Response {
                status: 422,
                body: json!({ "error": "validation failed", "fields": fields }).to_string(),
            },
        }
    }
}

struct Signup {
    name: String,
    email: String,
    age: u32,
}

fn validate_signup(s: &Signup) -> Result<(), ApiError> {
    let mut fields = BTreeMap::new();
    if s.name.trim().is_empty() {
        fields.insert(String::from("name"), String::from("required"));
    }
    if !s.email.contains('@') {
        fields.insert(String::from("email"), String::from("must contain @"));
    }
    if s.age < 13 {
        fields.insert(String::from("age"), String::from("must be at least 13"));
    }
    if fields.is_empty() { Ok(()) } else { Err(ApiError::Validation(fields)) }
}

