use serde_json::json;
use std::collections::HashMap;
use std::sync::Mutex;

#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    body: String,
}

struct Limiter {
    limit: u32,
    hits: Mutex<HashMap<String, u32>>,
}

impl Limiter {
    fn new(limit: u32) -> Self {
        Limiter { limit, hits: Mutex::new(HashMap::new()) }
    }

    fn check(&self, client: &str) -> Response {
        let mut hits = self.hits.lock().unwrap();
        let count = hits.entry(client.to_string()).or_insert(0);
        *count += 1;
        if *count <= self.limit {
            Response { status: 200, body: json!({ "remaining": self.limit - *count }).to_string() }
        } else {
            Response { status: 429, body: json!({ "error": "too many requests" }).to_string() }
        }
    }
}

