    assert_eq!(l.check("ana"), Response { status: 200, body: String::from(r#"{"remaining":0}"#) }, "2nd request");
    assert_eq!(l.check("ana"), Response { status: 429, body: String::from(r#"{"error":"too many requests"}"#) }, "3rd request");
