#[derive(Debug, Clone, Copy, PartialEq)]
enum Method {
    Get,
    Post,
}

struct Request {
    method: Method,
    path: String,
    body: String,
}

#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    body: String,
}

type Handler = Box<dyn Fn(&Request) -> Response>;

struct Router {
    routes: Vec<(Method, String, Handler)>,
}

impl Router {
    fn new() -> Self {
        Router { routes: Vec::new() }
    }

    fn route(mut self, method: Method, path: &str, handler: impl Fn(&Request) -> Response + 'static) -> Self {
        self.routes.push((method, path.to_string(), Box::new(handler)));
        self
    }

    fn handle(&self, req: &Request) -> Response {
        if let Some((_, _, handler)) = self.routes.iter().find(|(m, p, _)| *m == req.method && *p == req.path) {
            return handler(req);
        }
        if self.routes.iter().any(|(_, p, _)| *p == req.path) {
            Response { status: 405, body: String::from("method not allowed") }
        } else {
            Response { status: 404, body: String::from("not found") }
        }
    }
}

