use serde::de::DeserializeOwned;
use serde::Deserialize;

struct Request {
    body: String,
}

#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    body: String,
}

struct Json<T>(T);

trait FromRequest: Sized {
    fn from_request(req: &Request) -> Result<Self, Response>;
}

impl<T: DeserializeOwned> FromRequest for Json<T> {
    fn from_request(req: &Request) -> Result<Self, Response> {
        serde_json::from_str(&req.body)
            .map(Json)
            .map_err(|_| Response { status: 400, body: String::from("invalid JSON") })
    }
}

impl FromRequest for String {
    fn from_request(req: &Request) -> Result<Self, Response> {
        Ok(req.body.clone())
    }
}

fn call<A: FromRequest>(req: &Request, handler: impl Fn(A) -> Response) -> Response {
    match A::from_request(req) {
        Ok(arg) => handler(arg),
        Err(response) => response,
    }
}

