struct QueryBuilder {
    table: String,
    filters: Vec<String>,
    order: Option<String>,
    limit: Option<usize>,
}

impl QueryBuilder {
    fn new(table: &str) -> Self {
        QueryBuilder { table: table.to_string(), filters: Vec::new(), order: None, limit: None }
    }

    fn filter(mut self, condition: &str) -> Self {
        self.filters.push(condition.to_string());
        self
    }

    fn order_by(mut self, column: &str) -> Self {
        self.order = Some(column.to_string());
        self
    }

    fn limit(mut self, n: usize) -> Self {
        self.limit = Some(n);
        self
    }

    fn build(self) -> String {
        let mut sql = format!("SELECT * FROM {}", self.table);
        if !self.filters.is_empty() {
            sql.push_str(&format!(" WHERE {}", self.filters.join(" AND ")));
        }
        if let Some(column) = self.order {
            sql.push_str(&format!(" ORDER BY {column}"));
        }
        if let Some(n) = self.limit {
            sql.push_str(&format!(" LIMIT {n}"));
        }
        sql
    }
}

