patterns-idioms-3.solution:
#[derive(Debug, PartialEq)]
enum Connection {
    Disconnected,
    Connecting { attempt: u32 },
    Connected { session: String },
}

enum NetEvent {
    Dial,
    Timeout,
    Accepted(String),
    Hangup,
}

impl Connection {
    fn on(self, event: NetEvent) -> Connection {
        match (self, event) {
            (Connection::Disconnected, NetEvent::Dial) => Connection::Connecting { attempt: 1 },
            (Connection::Connecting { attempt }, NetEvent::Timeout) if attempt >= 3 => Connection::Disconnected,
            (Connection::Connecting { attempt }, NetEvent::Timeout) => Connection::Connecting { attempt: attempt + 1 },
            (Connection::Connecting { .. }, NetEvent::Accepted(session)) => Connection::Connected { session },
            (Connection::Connected { .. }, NetEvent::Hangup) => Connection::Disconnected,
            (state, _) => state,
        }
    }

    fn status(&self) -> String {
        match self {
            Connection::Disconnected => String::from("offline"),
            Connection::Connecting { attempt } => format!("dialing (attempt {attempt})"),
            Connection::Connected { session } => format!("online as {session}"),
        }
    }
}

