    let c = Connection::Disconnected.on(NetEvent::Dial);
    assert_eq!(c.status(), "dialing (attempt 1)", "after Dial");
    let c = c.on(NetEvent::Accepted(String::from("s-42")));
    assert_eq!(c.status(), "online as s-42", "after Accepted");
    assert_eq!(c.on(NetEvent::Hangup), Connection::Disconnected, "after Hangup");
}

#[test]
fn retries_three_times_then_gives_up() {
    let c = Connection::Disconnected.on(NetEvent::Dial).on(NetEvent::Timeout).on(NetEvent::Timeout);
    assert_eq!(c, Connection::Connecting { attempt: 3 }, "after two timeouts");
    assert_eq!(c.on(NetEvent::Timeout), Connection::Disconnected, "after the third timeout");
}

#[test]
fn other_events_change_nothing() {
    assert_eq!(Connection::Disconnected.on(NetEvent::Hangup), Connection::Disconnected, "Hangup while offline");
    let online = Connection::Connected { session: String::from("s") };
    assert_eq!(online.on(NetEvent::Dial), Connection::Connected { session: String::from("s") }, "Dial while online");
}

