struct Undo<'a> {
    list: &'a mut Vec<String>,
    start_len: usize,
    kept: bool,
}

impl<'a> Undo<'a> {
    fn begin(list: &'a mut Vec<String>) -> Self {
        let start_len = list.len();
        Undo { list, start_len, kept: false }
    }

    fn push(&mut self, item: &str) {
        self.list.push(item.to_string());
    }

    fn keep(mut self) {
        self.kept = true;
    }
}

impl Drop for Undo<'_> {
    fn drop(&mut self) {
        if !self.kept {
            self.list.truncate(self.start_len);
        }
    }
}

