use std::io::{self, BufRead};

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Level {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
}

fn parse_level(s: &str) -> Option<Level> {
    match s.trim().to_lowercase().as_str() {
        "trace" => Some(Level::Trace),
        "debug" => Some(Level::Debug),
        "info" => Some(Level::Info),
        "warn" | "warning" => Some(Level::Warn),
        "error" => Some(Level::Error),
        _ => None,
    }
}

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines().map(|l| l.expect("could not read input"));
    let min_text = lines.next().unwrap_or_default();
    let min = parse_level(&min_text).unwrap_or(Level::Info);
    let (mut shown, mut hidden) = (0, 0);
    for line in lines {
        let level_text = line.split_whitespace().next().unwrap_or("");
        match parse_level(level_text) {
            Some(level) if level >= min => {
                println!("{line}");
                shown += 1;
            }
            Some(_) => hidden += 1,
            None => {
                eprintln!("unknown level in {line:?}");
                hidden += 1;
            }
        }
    }
    println!("{shown} shown, {hidden} hidden");
}

