//! Splitting restaurant bills fairly.

/// Splits `total_cents` between `people` as evenly as possible.
///
/// The shares differ by at most one cent; the first people pay the extra cents.
///
/// # Examples
///
/// ```
/// assert_eq!(split_bill(1000, 3), vec![334, 333, 333]);
/// ```
///
/// # Panics
///
/// Panics if `people` is 0.
pub fn split_bill(total_cents: u32, people: u32) -> Vec<u32> {
    assert!(people > 0, "cannot split a bill between 0 people");
    let base = total_cents / people;
    let extra = total_cents % people;
    (0..people).map(|i| if i < extra { base + 1 } else { base }).collect()
}

