//! Arena league tools.

pub mod scoring {
    //! Turning match results into league points and ranks.

    /// Points for one win. A draw is worth 1 and a loss 0.
    pub const WIN_POINTS: u32 = 3;

    /// League points for a record of `wins` and `draws`.
    pub fn points(wins: u32, draws: u32) -> u32 {
        wins * WIN_POINTS + draws
    }

    /// The rank for a points total: bronze below 10, silver below 20, gold from 20.
    pub fn rank(points: u32) -> &'static str {
        match points {
            0..=9 => "bronze",
            10..=19 => "silver",
            _ => "gold",
        }
    }
}

