fn eval_rpn(expr: &str) -> Option<i64> {
    let mut stack: Vec<i64> = Vec::new();
    for token in expr.split_whitespace() {
        match token {
            "+" | "-" | "*" | "/" => {
                let b = stack.pop()?;
                let a = stack.pop()?;
                let value = match token {
                    "+" => a + b,
                    "-" => a - b,
                    "*" => a * b,
                    _ => a.checked_div(b)?,
                };
                stack.push(value);
            }
            _ => stack.push(token.parse().ok()?),
        }
    }
    if stack.len() == 1 { stack.pop() } else { None }
}

