fn days_until_warmer(temps: &[i32]) -> Vec<usize> {
    let mut answer = vec![0; temps.len()];
    let mut waiting: Vec<usize> = Vec::new();
    for (day, &t) in temps.iter().enumerate() {
        while let Some(&prev) = waiting.last() {
            if temps[prev] >= t {
                break;
            }
            answer[prev] = day - prev;
            waiting.pop();
        }
        waiting.push(day);
    }
    answer
}

