use std::collections::VecDeque;

fn round_robin(tasks: &[(&str, u32)], quantum: u32) -> Vec<String> {
    let mut queue: VecDeque<(&str, u32)> = tasks.iter().copied().collect();
    let mut finished = Vec::new();
    while let Some((name, left)) = queue.pop_front() {
        let run = left.min(quantum);
        if left - run == 0 {
            finished.push(name.to_string());
        } else {
            queue.push_back((name, left - run));
        }
    }
    finished
