collections-more-2.solution:
use std::collections::VecDeque;

struct RecentReadings {
    capacity: usize,
    readings: VecDeque<u64>,
    sum: u64,
}

impl RecentReadings {
    fn new(capacity: usize) -> Self {
        RecentReadings { capacity, readings: VecDeque::with_capacity(capacity + 1), sum: 0 }
    }

    fn push(&mut self, millis: u64) {
        self.readings.push_back(millis);
        self.sum += millis;
        if self.readings.len() > self.capacity {
            if let Some(old) = self.readings.pop_front() {
                self.sum -= old;
            }
        }
    }

    fn average(&self) -> Option<f64> {
        if self.readings.is_empty() {
            None
        } else {
            Some(self.sum as f64 / self.readings.len() as f64)
        }
    }
}

