use std::collections::BTreeMap;

fn price_at(history: &BTreeMap<u32, u32>, time: u32) -> Option<u32> {
    history.range(..=time).next_back().map(|(_, &price)| price)
}

fn changes_between(history: &BTreeMap<u32, u32>, from: u32, to: u32) -> usize {
    if from > to {
        return 0;
    }
    history.range(from..=to).count()
}

