collections-more-4.solution:
use std::collections::BTreeSet;

fn nearest_room(free: &BTreeSet<u32>, wanted: u32) -> Option<u32> {
    let below = free.range(..=wanted).next_back().copied();
    let above = free.range(wanted..).next().copied();
    match (below, above) {
        (Some(b), Some(a)) => {
            if wanted - b <= a - wanted { Some(b) } else { Some(a) }
        }
        (Some(b), None) => Some(b),
        (None, above) => above,
    }
}

