use std::collections::LinkedList;

fn move_last_to_front(list: &mut LinkedList<String>, k: usize) {
    if k == 0 || k >= list.len() {
        return;
    }
    let mut tail = list.split_off(list.len() - k);
    tail.append(list);
    *list = tail;
}

