use std::collections::{BTreeMap, HashMap};

struct LruCache {
    capacity: usize,
    tick: u64,
    entries: HashMap<String, (i32, u64)>,
    by_age: BTreeMap<u64, String>,
}

impl LruCache {
    fn new(capacity: usize) -> Self {
        LruCache { capacity, tick: 0, entries: HashMap::new(), by_age: BTreeMap::new() }
    }

    fn get(&mut self, key: &str) -> Option<i32> {
        let (value, used) = self.entries.get_mut(key)?;
        self.by_age.remove(&*used);
        self.tick += 1;
        *used = self.tick;
        self.by_age.insert(self.tick, key.to_string());
        Some(*value)
    }

    fn put(&mut self, key: &str, value: i32) {
        self.tick += 1;
        if let Some((old_value, used)) = self.entries.get_mut(key) {
            self.by_age.remove(&*used);
            *old_value = value;
            *used = self.tick;
        } else {
            self.entries.insert(key.to_string(), (value, self.tick));
            if self.entries.len() > self.capacity {
                if let Some((_, oldest)) = self.by_age.pop_first() {
                    self.entries.remove(&oldest);
                }
            }
        }
        self.by_age.insert(self.tick, key.to_string());
    }
}

