algorithms-1.solution:
use std::collections::HashMap;

fn two_sum(prices: &[i64], budget: i64) -> Option<(usize, usize)> {
    let mut first_index: HashMap<i64, usize> = HashMap::new();
    for (j, &p) in prices.iter().enumerate() {
        if let Some(&i) = first_index.get(&(budget - p)) {
            return Some((i, j));
        }
        first_index.entry(p).or_insert(j);
    }
    None
}

