algorithms-2.solution:
fn count_in_range(sorted: &[u32], low: u32, high: u32) -> usize {
    let start = sorted.partition_point(|&x| x < low);
    let end = sorted.partition_point(|&x| x <= high);
    end.saturating_sub(start)
}

