algorithms-2.solution:
fn days_needed(packages: &[u32], capacity: u32) -> u32 {
    let mut days = 1;
    let mut load = 0;
    for &p in packages {
        if load + p > capacity {
            days += 1;
            load = 0;
        }
        load += p;
    }
    days
}

fn min_capacity(packages: &[u32], days: u32) -> u32 {
    let Some(&heaviest) = packages.iter().max() else {
        return 0;
    };
    let mut lo = heaviest;
    let mut hi: u32 = packages.iter().sum();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if days_needed(packages, mid) <= days {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    lo
}

