algorithms-3.solution:
use std::io::{self, BufRead};

fn main() {
    let mut staff: Vec<(String, String, u32)> = Vec::new(); // (dept, name, salary)
    for line in io::stdin().lock().lines().skip(1) {
        let line = line.expect("read error");
        let fields: Vec<&str> = line.trim().split(',').collect();
        if let [name, dept, salary] = fields[..] {
            let salary: u32 = salary.parse().expect("salary must be a number");
            staff.push((dept.to_string(), name.to_string(), salary));
        }
    }
    staff.sort_by(|a, b| a.0.cmp(&b.0).then(b.2.cmp(&a.2)).then_with(|| a.1.cmp(&b.1)));
    let mut current_dept = "";
    for (dept, name, salary) in &staff {
        if dept != current_dept {
            println!("{dept}");
            current_dept = dept;
        }
        println!("  {:<8}{:>6}", name, salary);
    }
}

