fn sort_and_count(v: &[i32]) -> (Vec<i32>, u64) {
    if v.len() <= 1 {
        return (v.to_vec(), 0);
    }
    let (l, r) = v.split_at(v.len() / 2);
    let (left, a) = sort_and_count(l);
    let (right, b) = sort_and_count(r);
    let mut count = a + b;
    let mut out = Vec::with_capacity(v.len());
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i] <= right[j] {
            out.push(left[i]);
            i += 1;
        } else {
            out.push(right[j]);
            j += 1;
            count += (left.len() - i) as u64;
        }
    }
    out.extend_from_slice(&left[i..]);
    out.extend_from_slice(&right[j..]);
    (out, count)
}

fn count_inversions(v: &[i32]) -> u64 {
    sort_and_count(v).1
}

