fn dedup_sorted(v: &mut Vec<i32>) {
    if v.is_empty() {
        return;
    }
    let mut write = 1;
    for read in 1..v.len() {
        if v[read] != v[write - 1] {
            v[write] = v[read];
            write += 1;
        }
    }
    v.truncate(write);
}

