fn max_water(walls: &[u32]) -> u64 {
    if walls.len() < 2 {
        return 0;
    }
    let (mut i, mut j) = (0, walls.len() - 1);
    let mut best = 0;
    while i < j {
        let height = walls[i].min(walls[j]) as u64;
        best = best.max(height * (j - i) as u64);
        if walls[i] < walls[j] {
            i += 1;
        } else {
            j -= 1;
        }
    }
    best
}

