algorithms-6.solution:
fn shortest_at_least(values: &[u32], target: u64) -> Option<usize> {
    let mut best: Option<usize> = None;
    let mut left = 0;
    let mut sum: u64 = 0;
    for right in 0..values.len() {
        sum += values[right] as u64;
        while sum >= target && left <= right {
            let len = right + 1 - left;
            best = Some(best.map_or(len, |b| b.min(len)));
            sum -= values[left] as u64;
            left += 1;
        }
    }
    best
}

