algorithms-7.solution:
fn balance_point(values: &[i64]) -> Option<usize> {
    let total: i64 = values.iter().sum();
    let mut left = 0;
    for (i, &v) in values.iter().enumerate() {
        if left == total - left - v {
            return Some(i);
        }
        left += v;
    }
    None
}

