algorithms-7.solution:
use std::collections::HashMap;

fn count_subarrays_with_sum(values: &[i64], k: i64) -> u64 {
    let mut seen: HashMap<i64, u64> = HashMap::new();
    seen.insert(0, 1);
    let mut total = 0;
    let mut count = 0;
    for &v in values {
        total += v;
        if let Some(&n) = seen.get(&(total - k)) {
            count += n;
        }
        *seen.entry(total).or_insert(0) += 1;
    }
    count
}

