recursion-dp-1.solution:
fn pow_mod(base: u64, exp: u64, m: u64) -> u64 {
    if exp == 0 {
        return 1 % m;
    }
    let half = pow_mod(base, exp / 2, m);
    let square = half * half % m;
    if exp % 2 == 1 { square * (base % m) % m } else { square }
}

