recursion-dp-2.solution:
fn pick<'a>(players: &[&'a str], start: usize, k: usize, team: &mut Vec<&'a str>, out: &mut Vec<String>) {
    if team.len() == k {
        out.push(team.join("+"));
        return;
    }
    let still_needed = k - team.len();
    for i in start..players.len() {
        if players.len() - i < still_needed {
            break;
        }
        team.push(players[i]);
        pick(players, i + 1, k, team, out);
        team.pop();
    }
}

fn team_options(players: &[&str], k: usize) -> Vec<String> {
    let mut out = Vec::new();
    pick(players, 0, k, &mut Vec::new(), &mut out);
    out
}

