fn place(n: usize, row: usize, cols: &mut [bool], diag: &mut [bool], anti: &mut [bool]) -> usize {
    if row == n {
        return 1;
    }
    let mut count = 0;
    for col in 0..n {
        let (d, a) = (row + col, row + n - 1 - col);
        if cols[col] || diag[d] || anti[a] {
            continue;
        }
        cols[col] = true;
        diag[d] = true;
        anti[a] = true;
        count += place(n, row + 1, cols, diag, anti);
        cols[col] = false;
        diag[d] = false;
        anti[a] = false;
    }
    count
}

fn n_queens(n: usize) -> usize {
    place(n, 0, &mut vec![false; n], &mut vec![false; 2 * n], &mut vec![false; 2 * n])
}

