recursion-dp-3.solution:
use std::collections::HashMap;

fn routes(grid: &[Vec<u8>], r: usize, c: usize, memo: &mut HashMap<(usize, usize), u64>) -> u64 {
    let (rows, cols) = (grid.len(), grid[0].len());
    if r >= rows || c >= cols || grid[r][c] == b'#' {
        return 0;
    }
    if r == rows - 1 && c == cols - 1 {
        return 1;
    }
    if let Some(&known) = memo.get(&(r, c)) {
        return known;
    }
    let total = routes(grid, r + 1, c, memo) + routes(grid, r, c + 1, memo);
    memo.insert((r, c), total);
    total
}

fn count_paths(grid: &[&str]) -> u64 {
    let cells: Vec<Vec<u8>> = grid.iter().map(|row| row.bytes().collect()).collect();
    if cells.is_empty() || cells[0].is_empty() {
        return 0;
    }
    routes(&cells, 0, 0, &mut HashMap::new())
}

