recursion-dp-3.solution:
use std::collections::HashMap;

fn from(text: &str, start: usize, words: &[&str], memo: &mut HashMap<usize, bool>) -> bool {
    if start == text.len() {
        return true;
    }
    if let Some(&known) = memo.get(&start) {
        return known;
    }
    let ok = words
        .iter()
        .any(|w| !w.is_empty() && text[start..].starts_with(w) && from(text, start + w.len(), words, memo));
    memo.insert(start, ok);
    ok
}

fn can_segment(text: &str, words: &[&str]) -> bool {
    from(text, 0, words, &mut HashMap::new())
}

