recursion-dp-4.solution:
fn ways_to_pay(coins: &[u32], amount: u32) -> u64 {
    let amount = amount as usize;
    // ways[a] = number of ways to pay a with the coins seen so far
    let mut ways = vec![0u64; amount + 1];
    ways[0] = 1;
    for &coin in coins {
        let coin = coin as usize;
        for a in coin..=amount {
            ways[a] += ways[a - coin];
        }
    }
    ways[amount]
}

