fn max_tips(tips: &[u32]) -> u64 {
    // two_back = best up to house i - 2, one_back = best up to house i - 1
    let (mut two_back, mut one_back) = (0u64, 0u64);
    for &tip in tips {
        let best = one_back.max(two_back + tip as u64);
        two_back = one_back;
        one_back = best;
    }
    one_back
}

