fn min_path_cost(grid: &[Vec<u32>]) -> u32 {
    if grid.is_empty() || grid[0].is_empty() {
        return 0;
    }
    let (rows, cols) = (grid.len(), grid[0].len());
    // cost[r][c] = cheapest total to reach (r, c), including both ends
    let mut cost = vec![vec![0u32; cols]; rows];
    for r in 0..rows {
        for c in 0..cols {
            let before = match (r, c) {
                (0, 0) => 0,
                (0, _) => cost[r][c - 1],
                (_, 0) => cost[r - 1][c],
                _ => cost[r - 1][c].min(cost[r][c - 1]),
            };
            cost[r][c] = grid[r][c] + before;
        }
    }
    cost[rows - 1][cols - 1]
}

