fn can_split_evenly(weights: &[u32]) -> bool {
    let total: u32 = weights.iter().sum();
    if total % 2 == 1 {
        return false;
    }
    let half = (total / 2) as usize;
    // can[s] = some of the parcels seen so far add up to exactly s
    let mut can = vec![false; half + 1];
    can[0] = true;
    for &w in weights {
        let w = w as usize;
        for s in (w..=half).rev() {
            if can[s - w] {
                can[s] = true;
            }
        }
    }
    can[half]
}

