use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("read error");
    let mut lines = input.lines();
    let capacity: usize = lines.next().unwrap_or("0").trim().parse().expect("capacity");
    let mut items: Vec<(&str, usize, u32)> = Vec::new();
    for line in lines {
        let parts: Vec<&str> = line.split_whitespace().collect();
        if let [name, weight, value] = parts[..] {
            items.push((name, weight.parse().expect("weight"), value.parse().expect("value")));
        }
    }
    let n = items.len();
    let mut best = vec![vec![0u32; capacity + 1]; n + 1];
    for i in 1..=n {
        let (_, weight, value) = items[i - 1];
        for w in 0..=capacity {
            best[i][w] = best[i - 1][w];
            if weight <= w {
                best[i][w] = best[i][w].max(best[i - 1][w - weight] + value);
            }
        }
    }
    let mut chosen = Vec::new();
    let mut w = capacity;
    for i in (1..=n).rev() {
        if best[i][w] != best[i - 1][w] {
            chosen.push(i - 1);
            w -= items[i - 1].1;
        }
    }
    chosen.reverse();
    let names: Vec<&str> = chosen.iter().map(|&i| items[i].0).collect();
    let weight: usize = chosen.iter().map(|&i| items[i].1).sum();
    if names.is_empty() {
        println!("take: nothing");
    } else {
        println!("take: {}", names.join(", "));
    }
    println!("weight: {weight}/{capacity}");
    println!("value: {}", best[n][capacity]);
}

