fn find_hub(n: usize, follows: &[(usize, usize)]) -> Option<usize> {
    let mut followers = vec![0; n];
    let mut following = vec![0; n];
    for &(a, b) in follows {
        following[a] += 1;
        followers[b] += 1;
    }
    (0..n).find(|&p| followers[p] == n - 1 && following[p] == 0)
}

