fn largest_island(map: &[&str]) -> usize {
    let grid: Vec<&[u8]> = map.iter().map(|row| row.as_bytes()).collect();
    let mut seen: Vec<Vec<bool>> = grid.iter().map(|row| vec![false; row.len()]).collect();
    let mut best = 0;
    for r in 0..grid.len() {
        for c in 0..grid[r].len() {
            if grid[r][c] != b'#' || seen[r][c] {
                continue;
            }
            seen[r][c] = true;
            let mut stack = vec![(r, c)];
            let mut size = 0;
            while let Some((y, x)) = stack.pop() {
                size += 1;
                for (ny, nx) in [(y.wrapping_sub(1), x), (y + 1, x), (y, x.wrapping_sub(1)), (y, x + 1)] {
                    if matches!(grid.get(ny).and_then(|row| row.get(nx)), Some(&b'#')) && !seen[ny][nx] {
                        seen[ny][nx] = true;
                        stack.push((ny, nx));
                    }
                }
            }
            best = best.max(size);
        }
    }
    best
}

