use std::collections::{BTreeMap, BTreeSet};
use std::io::{self, BufRead};

fn main() {
    let mut waiting_on: BTreeMap<String, usize> = BTreeMap::new();
    let mut unblocks: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for line in io::stdin().lock().lines() {
        let line = line.expect("read error");
        let Some((job, deps)) = line.split_once(':') else {
            continue;
        };
        let job = job.trim().to_string();
        waiting_on.entry(job.clone()).or_insert(0);
        for dep in deps.split_whitespace() {
            waiting_on.entry(dep.to_string()).or_insert(0);
            *waiting_on.entry(job.clone()).or_insert(0) += 1;
            unblocks.entry(dep.to_string()).or_default().push(job.clone());
        }
    }
    let mut ready: BTreeSet<String> = waiting_on.iter().filter(|(_, n)| **n == 0).map(|(j, _)| j.clone()).collect();
    let mut order = Vec::new();
    while let Some(job) = ready.pop_first() {
        if let Some(next) = unblocks.get(&job) {
            for waiter in next {
                if let Some(n) = waiting_on.get_mut(waiter) {
                    *n -= 1;
                    if *n == 0 {
                        ready.insert(waiter.clone());
                    }
                }
            }
        }
        order.push(job);
    }
    if order.len() < waiting_on.len() {
        let stuck: Vec<&str> = waiting_on.iter().filter(|(_, n)| **n > 0).map(|(j, _)| j.as_str()).collect();
        println!("cycle: {}", stuck.join(", "));
        std::process::exit(1);
    }
    for (i, job) in order.iter().enumerate() {
        println!("{}. {job}", i + 1);
    }
}

