fn min_semesters(n: usize, prereqs: &[(usize, usize)]) -> Option<usize> {
    let mut next: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut indegree = vec![0; n];
    for &(a, b) in prereqs {
        next[a].push(b);
        indegree[b] += 1;
    }
    let mut layer: Vec<usize> = (0..n).filter(|&c| indegree[c] == 0).collect();
    let mut taken = 0;
    let mut semesters = 0;
    while !layer.is_empty() {
        semesters += 1;
        taken += layer.len();
        let mut next_layer = Vec::new();
        for &c in &layer {
            for &d in &next[c] {
                indegree[d] -= 1;
                if indegree[d] == 0 {
                    next_layer.push(d);
                }
            }
        }
        layer = next_layer;
    }
    if taken == n { Some(semesters) } else { None }
}

