use std::cmp::Reverse;
use std::collections::BinaryHeap;

fn time_to_reach_all(n: usize, links: &[(usize, usize, u64)], source: usize) -> Option<u64> {
    let mut adj: Vec<Vec<(usize, u64)>> = vec![Vec::new(); n];
    for &(from, to, millis) in links {
        adj[from].push((to, millis));
    }
    let mut dist = vec![u64::MAX; n];
    let mut heap = BinaryHeap::new();
    dist[source] = 0;
    heap.push(Reverse((0, source)));
    while let Some(Reverse((d, u))) = heap.pop() {
        if d > dist[u] {
            continue;
        }
        for &(v, w) in &adj[u] {
            if d + w < dist[v] {
                dist[v] = d + w;
                heap.push(Reverse((d + w, v)));
            }
        }
    }
    let slowest = dist.into_iter().max()?;
    if slowest == u64::MAX { None } else { Some(slowest) }
}

