use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("read error");
    let mut lines = input.lines();
    let first = lines.next().unwrap_or("");
    let mut ends = first.split_whitespace();
    let (from, to) = (ends.next().unwrap_or(""), ends.next().unwrap_or(""));
    if from == to {
        println!("{from} (0)");
        return;
    }
    let mut index: HashMap<String, usize> = HashMap::new();
    let mut names: Vec<String> = Vec::new();
    let mut adj: Vec<Vec<(usize, u64)>> = Vec::new();
    for line in lines {
        let parts: Vec<&str> = line.split_whitespace().collect();
        let [a, b, minutes] = parts[..] else {
            continue;
        };
        let minutes: u64 = minutes.parse().expect("minutes");
        let mut id = |name: &str| -> usize {
            if let Some(&i) = index.get(name) {
                return i;
            }
            index.insert(name.to_string(), names.len());
            names.push(name.to_string());
            adj.push(Vec::new());
            names.len() - 1
        };
        let (ia, ib) = (id(a), id(b));
        adj[ia].push((ib, minutes));
        adj[ib].push((ia, minutes));
    }
    let (Some(&start), Some(&goal)) = (index.get(from), index.get(to)) else {
        println!("no route");
        return;
    };
    let mut dist = vec![u64::MAX; names.len()];
    let mut parent: Vec<Option<usize>> = vec![None; names.len()];
    let mut heap = BinaryHeap::new();
    dist[start] = 0;
    heap.push(Reverse((0, start)));
    while let Some(Reverse((d, u))) = heap.pop() {
        if d > dist[u] {
            continue;
        }
        for &(v, w) in &adj[u] {
            if d + w < dist[v] {
                dist[v] = d + w;
                parent[v] = Some(u);
                heap.push(Reverse((d + w, v)));
            }
        }
    }
    if dist[goal] == u64::MAX {
        println!("no route");
        return;
    }
    let mut route = vec![goal];
    let mut cur = goal;
    while let Some(p) = parent[cur] {
        route.push(p);
        cur = p;
    }
    route.reverse();
    let cities: Vec<&str> = route.iter().map(|&i| names[i].as_str()).collect();
    println!("{} ({})", cities.join(" -> "), dist[goal]);
}

