fn within(slot: &Option<Box<Node>>, low: Option<i32>, high: Option<i32>) -> bool {
    let Some(node) = slot else {
        return true;
    };
    if low.is_some_and(|l| node.value <= l) || high.is_some_and(|h| node.value >= h) {
        return false;
    }
    within(&node.left, low, Some(node.value)) && within(&node.right, Some(node.value), high)
}

fn is_valid_bst(root: &Option<Box<Node>>) -> bool {
    within(root, None, None)
}

