fn find(parent: &mut [usize], x: usize) -> usize {
    let mut root = x;
    while parent[root] != root {
        root = parent[root];
    }
    let mut cur = x;
    while parent[cur] != root {
        let next = parent[cur];
        parent[cur] = root;
        cur = next;
    }
    root
}

fn first_redundant(n: usize, cables: &[(usize, usize)]) -> Option<(usize, usize)> {
    let mut parent: Vec<usize> = (0..n).collect();
    for &(a, b) in cables {
        let (ra, rb) = (find(&mut parent, a), find(&mut parent, b));
        if ra == rb {
            return Some((a, b));
        }
