fn find(parent: &mut [usize], x: usize) -> usize {
    let mut root = x;
    while parent[root] != root {
        root = parent[root];
    }
    let mut cur = x;
    while parent[cur] != root {
        let next = parent[cur];
        parent[cur] = root;
        cur = next;
    }
    root
}

fn min_cable_cost(n: usize, options: &[(usize, usize, u64)]) -> Option<u64> {
    let mut sorted = options.to_vec();
    sorted.sort_unstable_by_key(|&(_, _, cost)| cost);
    let mut parent: Vec<usize> = (0..n).collect();
    let mut total = 0;
    let mut cables = 0;
    for (a, b, cost) in sorted {
        let (ra, rb) = (find(&mut parent, a), find(&mut parent, b));
        if ra != rb {
            parent[ra] = rb;
            total += cost;
            cables += 1;
        }
    }
    if cables + 1 >= n { Some(total) } else { None }
}

