use std::io::{self, BufRead};

fn hour_of(line: &str) -> Option<u32> {
    let fields: Vec<&str> = line.split_whitespace().collect();
    if fields.len() != 5 {
        return None;
    }
    let hour: u32 = fields[0].get(11..13)?.parse().ok()?;
    (hour < 24).then_some(hour)
}

fn main() {
    let mut per_hour: BTreeMap<u32, usize> = BTreeMap::new();
    for line in io::stdin().lock().lines() {
        let line = line.expect("read error");
        if let Some(hour) = hour_of(&line) {
            *per_hour.entry(hour).or_insert(0) += 1;
        }
    }
    if per_hour.is_empty() {
        println!("no traffic");
    }
    for (hour, count) in &per_hour {
        println!("{hour:02}:00 {} {count}", "#".repeat(*count));
    }
}

