use std::collections::VecDeque;
use std::io::{self, BufRead};

fn main() {
    let threshold = match std::env::args().nth(1).and_then(|a| a.parse::<usize>().ok()) {
        Some(n) if n > 0 => n,
        _ => {
            eprintln!("usage: alerts THRESHOLD");
            std::process::exit(2);
        }
    };
    let mut window: VecDeque<u64> = VecDeque::new();
    let mut alerts = 0;
    for line in io::stdin().lock().lines() {
        let line = line.expect("read error");
        let fields: Vec<&str> = line.split_whitespace().collect();
        let [time, _, _, status, _] = fields[..] else {
            continue;
        };
        let (Ok(t), Ok(status)) = (time.parse::<u64>(), status.parse::<u16>()) else {
            continue;
        };
        if status < 500 {
            continue;
        }
        while window.front().is_some_and(|&old| t - old >= 60) {
            window.pop_front();
        }
        window.push_back(t);
        if window.len() >= threshold {
            println!("ALERT at {t}: {} server errors in 60s", window.len());
            alerts += 1;
            window.clear();
        }
    }
    println!("alerts: {alerts}");
}

