use std::collections::HashMap;

struct Product {
    name: String,
    price_cents: u64,
    stock: u32,
}

struct Inventory {
    products: HashMap<String, Product>,
}

impl Inventory {
    fn new() -> Self {
        Inventory { products: HashMap::new() }
    }

    fn add_product(&mut self, sku: &str, name: &str, price_cents: u64, stock: u32) {
        self.products.insert(sku.to_string(), Product { name: name.to_string(), price_cents, stock });
    }

    fn value_of_stock_cents(&self) -> u64 {
        self.products.values().map(|p| p.price_cents * p.stock as u64).sum()
    }

    fn low_stock(&self, threshold: u32) -> Vec<String> {
        let mut low: Vec<(&String, &Product)> = self.products.iter().filter(|(_, p)| p.stock < threshold).collect();
        low.sort_by(|a, b| a.1.stock.cmp(&b.1.stock).then(a.0.cmp(b.0)));
        low.iter().map(|(sku, p)| format!("{sku} ({}): {} left", p.name, p.stock)).collect()
    }
}

