capstone-3.solution:
trait Discount {
    fn label(&self) -> String;
    fn amount_off(&self, subtotal_cents: u64, items: u32) -> u64;
}

struct PercentOff {
    percent: u64,
}

struct BulkDeal {
    min_items: u32,
    off_cents: u64,
}

struct Coupon {
    code: String,
    off_cents: u64,
}

impl Discount for PercentOff {
    fn label(&self) -> String {
        format!("{}% off", self.percent)
    }

    fn amount_off(&self, subtotal_cents: u64, _items: u32) -> u64 {
        subtotal_cents * self.percent / 100
    }
}

impl Discount for BulkDeal {
    fn label(&self) -> String {
        format!("bulk deal ({}+ items)", self.min_items)
    }

    fn amount_off(&self, _subtotal_cents: u64, items: u32) -> u64 {
        if items >= self.min_items { self.off_cents } else { 0 }
    }
}

impl Discount for Coupon {
    fn label(&self) -> String {
        format!("coupon {}", self.code)
    }

    fn amount_off(&self, _subtotal_cents: u64, _items: u32) -> u64 {
        self.off_cents
    }
}

fn checkout(subtotal_cents: u64, items: u32, discounts: &[Box<dyn Discount>]) -> (u64, Vec<String>) {
    let mut total_off = 0;
    let mut applied = Vec::new();
    for d in discounts {
        let off = d.amount_off(subtotal_cents, items);
        if off > 0 {
            total_off += off;
            applied.push(d.label());
        }
    }
    (subtotal_cents.saturating_sub(total_off), applied)
}

