use serde_json::Value;
use std::collections::BTreeSet;
use std::io::{self, Read};

fn diff(path: &str, old: &Value, new: &Value, out: &mut Vec<String>) {
    match (old, new) {
        (Value::Object(a), Value::Object(b)) => {
            let keys: BTreeSet<&String> = a.keys().chain(b.keys()).collect();
            for key in keys {
                let child = if path.is_empty() { key.clone() } else { format!("{path}.{key}") };
                match (a.get(key), b.get(key)) {
                    (Some(x), Some(y)) => diff(&child, x, y, out),
                    (Some(_), None) => out.push(format!("- {child}")),
                    (None, Some(y)) => out.push(format!("+ {child}: {y}")),
                    (None, None) => {}
                }
            }
        }
        _ => {
            if old != new {
                out.push(format!("~ {path}: {old} -> {new}"));
            }
        }
    }
}

fn parse(text: &str, name: &str) -> Value {
    serde_json::from_str(text).unwrap_or_else(|e| {
        println!("{name} is not valid JSON: {e}");
        std::process::exit(2);
    })
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("read error");
    let (staging, production) = input.split_once("\n---\n").unwrap_or((input.as_str(), ""));
    let (old, new) = (parse(staging, "staging"), parse(production, "production"));
    let mut out = Vec::new();
    diff("", &old, &new, &mut out);
    if out.is_empty() {
        println!("no drift");
    }
    for line in &out {
        println!("{line}");
    }
}

