use std::collections::BTreeMap;
use std::io::{self, BufRead};

#[derive(Clone)]
enum TicketState {
    Open,
    InProgress { assignee: String },
    Resolved,
    Closed,
}

impl TicketState {
    fn describe(&self) -> String {
        match self {
            TicketState::Open => "open".to_string(),
            TicketState::InProgress { assignee } => format!("in progress ({assignee})"),
            TicketState::Resolved => "resolved".to_string(),
            TicketState::Closed => "closed".to_string(),
        }
    }
}

fn act(state: &TicketState, action: &str, name: Option<&str>) -> Option<TicketState> {
    match (state, action, name) {
        (TicketState::Open | TicketState::InProgress { .. }, "assign", Some(n)) => Some(TicketState::InProgress { assignee: n.to_string() }),
        (TicketState::InProgress { .. }, "resolve", _) => Some(TicketState::Resolved),
        (TicketState::Resolved, "reopen", _) => Some(TicketState::Open),
        (TicketState::Resolved, "close", _) => Some(TicketState::Closed),
        _ => None,
    }
}

fn main() {
    let mut tickets: BTreeMap<String, TicketState> = BTreeMap::new();
    for line in io::stdin().lock().lines() {
        let line = line.expect("read error");
        let mut parts = line.split_whitespace();
        let (Some(id), Some(action)) = (parts.next(), parts.next()) else {
            continue;
        };
        let name = parts.next();
        let known = matches!(action, "resolve" | "reopen" | "close") || (action == "assign" && name.is_some());
        if !known {
            continue;
        }
        let state = tickets.entry(id.to_string()).or_insert(TicketState::Open);
        match act(state, action, name) {
            Some(next) => *state = next,
            None => println!("rejected: {id} {action} (ticket is {})", state.describe()),
        }
    }
    for (id, state) in &tickets {
        println!("{id}: {}", state.describe());
    }
}

