struct Draft {
    title: String,
    body: String,
}

struct InReview {
    title: String,
    body: String,
}

struct Published {
    title: String,
    body: String,
    approved_by: String,
}

impl Draft {
    fn new(title: &str) -> Draft {
        Draft { title: title.to_string(), body: String::new() }
    }

    fn write(mut self, text: &str) -> Draft {
        if !self.body.is_empty() {
            self.body.push(' ');
        }
        self.body.push_str(text);
        self
    }

    fn submit(self) -> InReview {
        InReview { title: self.title, body: self.body }
    }
}

impl InReview {
    fn approve(self, reviewer: &str) -> Published {
        Published { title: self.title, body: self.body, approved_by: reviewer.to_string() }
    }

    fn reject(self) -> Draft {
        Draft { title: self.title, body: self.body }
    }
}

impl Published {
    fn headline(&self) -> String {
        format!("{} (approved by {})", self.title, self.approved_by)
    }

    fn body(&self) -> &str {
        &self.body
    }
}

