capstone-6.solution:
enum Speed {
    Standard,
    Express,
}

enum Zone {
    Domestic,
    International,
}

// Prices in cents.
fn ship_cost(weight_kg: u32, speed: Speed, zone: Zone, member: bool) -> u32 {
    let (base, per_kg) = match (zone, speed) {
        (Zone::Domestic, Speed::Standard) => (500, 100),
        (Zone::Domestic, Speed::Express) => (1500, 200),
        (Zone::International, Speed::Standard) => (2500, 300),
        (Zone::International, Speed::Express) => (4000, 600),
    };
    let cost = base + weight_kg * per_kg;
    if member {
        cost - cost / 10 // members get 10% off
    } else {
        cost
    }
}

